// spec: specs/orders.md §25 · кейсы .qa/tests/orders/ord-40-edit-price-field-width.md, ord-38
// seed: tests/seed.admin.spec.ts
// #af3ea6 (עבר QA 26.10): «עריכת הזמנה», поле «מחיר יחידה» шириной не меньше 160px (₪ + 6 цифр + агорот); если рядом с кол-вом
//   места нет (1024 с боковым меню, карточка ~242px) — поле на своей строке во всю ширину. Введённые 50000 и 500000.50 видны
//   целиком (scrollWidth ≤ clientWidth), «סה"כ» строки пересчитан. Регресс: #cb3f40 (320–414: «₪1,000.00» целиком, не «₪1,00»,
//   без прокрутки вбок) и #c6b040 (641 — ряды, контейнер < 600).
// Без сохранения: в конце «ביטול», заказ прежний «— 1 ₪1.00 ₪1.00».
// Данные: товар QA-AUTO-af3e-<ts> (₪1, остаток 3 «ללא מקום») + заказ клиента test ×1 («ממתינה לאישור»); afterAll — отклонить, удалить.
import { test, expect, Page } from '@playwright/test';
import { auth, createStockedProduct, buyerPlaceOrder, openOrder, cleanup } from './_qa-order';

test.use({ storageState: auth('admin') });
test.describe.configure({ mode: 'serial' });

const ts = `${String(Date.now()).slice(-7)}${Math.floor(Math.random() * 10)}`;
const P = `QA-AUTO-af3e-${ts}`;
let orderNo: string | undefined;
let productCreated = false;

const price = (page: Page) => page.getByRole('spinbutton', { name: `מחיר יחידה — ${P}`, exact: true });
const cardRow = (page: Page) => page.getByText(P, { exact: true }).first().locator('..');
const fmt = (n: number) => '₪' + n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

type Box = { l: number; t: number; r: number; b: number };

/** Замер поля цены, степпера кол-ва, суммы строки и карточки «פריטי ההזמנה» (только чтение DOM). */
const measure = (page: Page) => page.evaluate((n) => {
  const bx = (e: Element) => { const b = e.getBoundingClientRect(); return { l: b.left, t: b.top, r: b.right, b: b.bottom }; };
  const vis = (e: Element) => e.getClientRects().length > 0 && getComputedStyle(e).visibility !== 'hidden';
  const h = [...document.querySelectorAll('h1,h2,h3,h4')].find((e) => e.textContent!.trim() === 'פריטי ההזמנה')!;
  const card = h.parentElement!;
  const pi = document.querySelector(`input[aria-label="מחיר יחידה — ${n}"]`) as HTMLInputElement;
  const plus = document.querySelector(`button[aria-label="הוספת יחידה — ${n}"]`)!;
  const minus = document.querySelector(`button[aria-label="הפחתת יחידה — ${n}"]`)!;
  const del = document.querySelector(`button[aria-label="הסרת ${n}"]`)!;
  let row: Element | null = pi; while (row && !row.contains(del)) row = row.parentElement;
  const leaves = [...row!.querySelectorAll('*')].filter((e) => e.children.length === 0 && vis(e));
  const totEl = leaves.filter((e) => /^₪[\d,]+\.\d\d$/.test(e.textContent!.trim())).pop();
  const hdr = [...card.querySelectorAll('*')].find((e) => e.children.length === 0 && e.textContent!.trim() === 'שם מוצר');
  const scrollers = [card, ...card.querySelectorAll('*')].filter((e) => vis(e) && e.scrollWidth > e.clientWidth + 1 && ['auto', 'scroll'].includes(getComputedStyle(e).overflowX))
    .map((e) => `${e.tagName} sw${e.scrollWidth}/cw${e.clientWidth}`);
  const stepper = [bx(plus), bx(minus)];
  return {
    vw: innerWidth, docSW: document.documentElement.scrollWidth, scrollX, cardSW: card.scrollWidth, cardCW: card.clientWidth, card: bx(card), scrollers,
    containerW: (pi.closest('[class*="@container"]') ?? card).getBoundingClientRect().width,
    price: bx(pi), priceW: pi.getBoundingClientRect().width, priceSW: pi.scrollWidth, priceCW: pi.clientWidth, value: pi.value,
    stepper: { l: Math.min(stepper[0].l, stepper[1].l), t: Math.min(stepper[0].t, stepper[1].t), r: Math.max(stepper[0].r, stepper[1].r), b: Math.max(stepper[0].b, stepper[1].b) },
    tot: totEl ? totEl.textContent!.trim() : null, totBox: totEl ? bx(totEl) : null, totClip: totEl ? totEl.scrollWidth > totEl.clientWidth + 1 : true,
    hdrVisible: !!hdr && vis(hdr),
  };
}, P);

const inside = (a: Box, c: Box) => a.l >= c.l - 0.5 && a.r <= c.r + 0.5;

async function typePrice(page: Page, v: string) {
  await price(page).fill(v);
  await price(page).press('Tab');
  await expect(page.getByText(fmt(Number(v)), { exact: true }).first(), `сумма строки ${fmt(Number(v))}`).toBeVisible();
}

/** Проверки одной ширины. ownLine — поле цены ожидается на своей строке во всю ширину (1024 с меню). */
async function checkWidth(page: Page, W: number, H: number, opts: { ownLine?: boolean; rows?: boolean; phone?: boolean } = {}) {
  await page.setViewportSize({ width: W, height: H });
  await expect.poll(() => page.evaluate(() => innerWidth)).toBe(W);
  const tag0 = `${W}×${H}`;

  if (opts.phone) {
    // #cb3f40: «₪1,000.00» целиком (было «₪1,00»), без прокрутки вбок
    await typePrice(page, '1000');
    const m = await measure(page);
    expect(m.tot, `${tag0}: сумма строки`).toBe('₪1,000.00');
    expect(m.totClip, `${tag0}: «₪1,000.00» не обрезана`).toBe(false);
    expect(inside(m.totBox!, m.card), `${tag0}: «₪1,000.00» внутри карточки`).toBe(true);
    expect(m.docSW, `${tag0}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
  }

  for (const v of ['50000', '500000.50']) {
    await typePrice(page, v);
    const m = await measure(page);
    const tag = `${tag0}, цена ${v}`;
    expect(m.value, `${tag}: значение в поле`).toBe(v);
    expect(m.priceW, `${tag}: ширина поля «מחיר יחידה» ≥ 160px`).toBeGreaterThanOrEqual(159.5);
    expect(m.priceSW, `${tag}: значение видно целиком (scrollWidth ≤ clientWidth)`).toBeLessThanOrEqual(m.priceCW);
    expect(inside(m.price, m.card), `${tag}: поле цены внутри карточки`).toBe(true);
    expect(m.tot, `${tag}: «סה"כ» строки пересчитан`).toBe(fmt(Number(v)));
    expect(m.totClip, `${tag}: «סה"כ» строки не обрезан`).toBe(false);
    expect(inside(m.totBox!, m.card), `${tag}: «סה"כ» строки внутри карточки`).toBe(true);
    expect(m.docSW, `${tag}: страница без прокрутки вбок`).toBeLessThanOrEqual(m.vw + 1);
    expect(m.scrollX, `${tag}: окно не прокручено вбок`).toBe(0);
    expect(m.cardSW, `${tag}: карточка без прокрутки вбок`).toBeLessThanOrEqual(m.cardCW + 1);
    expect(m.scrollers, `${tag}: внутри карточки нет прокручиваемых вбок блоков`).toEqual([]);
    if (opts.ownLine) {
      expect(m.price.t, `${tag}: поле цены на своей строке — ниже степпера кол-ва`).toBeGreaterThanOrEqual(m.stepper.b - 0.5);
      expect(m.priceW, `${tag}: поле цены во всю ширину блока (${Math.round(m.containerW)}px)`).toBeGreaterThanOrEqual(m.containerW - 2);
    }
    if (opts.rows) {
      expect(m.containerW, `${tag}: блок < 600 — ряды`).toBeLessThan(600);
      expect(m.hdrVisible, `${tag}: ряды — заголовков таблицы нет`).toBe(false);
    }
  }
}

async function openEdit(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await openOrder(page, orderNo!);
  await page.getByRole('button', { name: 'עריכה', exact: true }).click();
  await expect(page.getByRole('heading', { level: 1, name: `עריכת הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(price(page)).toBeVisible();
}

async function cancelAndCheckUnchanged(page: Page) {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.getByRole('button', { name: 'ביטול', exact: true }).click(); // ничего не сохраняем
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${orderNo}` })).toBeVisible({ timeout: 20_000 });
  await expect(cardRow(page), 'заказ не изменился').toHaveText(/—\s*1\s*₪1\.00\s*₪1\.00/);
  await page.reload();
  await expect(cardRow(page), 'заказ не изменился (после reload)').toHaveText(/—\s*1\s*₪1\.00\s*₪1\.00/, { timeout: 20_000 });
}

test.describe('orders — עריכת הזמנה: שדה «מחיר יחידה» ≥160px, המחיר נראה במלואו (#af3ea6)', () => {
  test.beforeAll(async ({ browser }) => {
    test.setTimeout(240_000);
    const ctx = await browser.newContext({ storageState: auth('admin'), locale: 'he-IL', viewport: { width: 1440, height: 900 } });
    let id: string;
    try {
      productCreated = true;
      id = await createStockedProduct(await ctx.newPage(), P, `QAF3E-${ts}`, 1, 3);
    } finally { await ctx.close(); }
    orderNo = await buyerPlaceOrder(browser, [{ id, name: P, qty: 1 }], `QA-AUTO-af3e-${ts}`);
  });
  test.afterAll(async ({ browser }) => {
    test.setTimeout(180_000);
    await cleanup(browser, [orderNo], productCreated ? [P] : []);
  });

  test('1024 עם תפריט צד: השדה בשורה משלו ברוחב מלא, 50000 ו-500000.50 במלואם; 641 שורות; 768/1100/1280/1440 — ≥160px #af3ea6 #c6b040 @desktop @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEdit(page);
    await checkWidth(page, 1024, 768, { ownLine: true, rows: true });
    await expect(page.getByRole('button', { name: 'כיווץ', exact: true }), '1024: боковое меню открыто').toBeVisible();
    await checkWidth(page, 641, 900, { rows: true });
    for (const [w, h] of [[768, 1024], [1100, 800], [1280, 800], [1440, 900]] as const) await checkWidth(page, w, h);
    await cancelAndCheckUnchanged(page);
  });

  test('טלפון 320/360/390/414: 500000.50 במלואו, «₪1,000.00» ולא «₪1,00», בלי גלילה לרוחב #af3ea6 #cb3f40 @iphone @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    await openEdit(page);
    for (const [w, h] of [[320, 568], [360, 740], [390, 844], [414, 896]] as const) await checkWidth(page, w, h, { phone: true, rows: true });
    await cancelAndCheckUnchanged(page);
  });
});
